window.kbPageData["views/entry/k-d6674c45a19ed076"] = {"key":"entry/k-d6674c45a19ed076","state":{"route":"entry/k-d6674c45a19ed076"},"node":{"id":"k-d6674c45a19ed076","mode":"k","title":"商品经济理论 · 商品","type":"概念与词义","domain":"经济","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"主类":["概念与词义"],"出处性质":["理论手册"],"学科":["经济"],"来源主题":["马克思主义政治经济学"],"资料类别":["非时政"]},"seeAlso":["k-8052f9e5fa281e6a","k-ea788f07484357b9"],"directorySummary":"一、商品\n商品是用来交换的能满足人们某种需要的劳动产品，具有使用价值和价值两种属性。\n1.使用价值：能满足人们某种需要的物品的效用，即物品的有用性。这是商品本身就有、\n天生自带的属性，叫作自然属性。\n2.价值：凝结在商品中的无差别的人类劳动。是商品的社会属性。\n3.商品二因素之间的关系\n统一性：作为…","sources":[{"id":"8c2bf41475ff9995","label":"商品经济理论 · 商品","topic":"马克思主义政治经济学","category":"非时政","text":"一、商品\n商品是用来交换的能满足人们某种需要的劳动产品，具有使用价值和价值两种属性。\n1.使用价值：能满足人们某种需要的物品的效用，即物品的有用性。这是商品本身就有、\n天生自带的属性，叫作自然属性。\n2.价值：凝结在商品中的无差别的人类劳动。是商品的社会属性。\n3.商品二因素之间的关系\n统一性：作为一个商品，必须同时拥有使用价值和价值，其中使用价值是价值的物质承\n担者，没有使用价值的物品则没有价值，价值寓于使用价值之中。\n对立性：生产者只能让渡商品的使用价值来获得其价值，而消费者要让渡商品的价值来\n获得其使用价值，故二者相互排斥，不可兼得。\n（粉笔敲黑板：通过关键词理解商品的含义，区分价值和使用价值）","source":{"doc":"3ccc56f4000d1642c2d1","first":8,"last":8,"page":8,"file":"政治理论必学手册.pdf"},"basis":"理论手册"}]},"questions":{},"terms":{"k-8052f9e5fa281e6a":{"id":"k-8052f9e5fa281e6a","mode":"k","type":"概念与词义","title":"商品的价值","qs":[],"count":0},"k-ea788f07484357b9":{"id":"k-ea788f07484357b9","mode":"k","type":"概念与词义","title":"商品的使用价值","qs":[],"count":0}},"references":{},"topics":[],"units":{"k-d6674c45a19ed076":[]}};
